}
try{
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
  csrf_check();$action=(string)($_POST['action']??'');
  if($action==='clear_cache'){$key=(string)($_POST['cache_key']??'');$result=sk980_clear_cache($key);sk980_audit('cache_clear','Cleared application cache location',$result,$uid);$flash='Selected cache cleared.';}
  elseif($action==='clear_all_cache'){if((string)($_POST['confirm_text']??'')!=='CLEAR ALL CACHE')throw new RuntimeException('Type exactly: CLEAR ALL CACHE');$result=sk980_clear_all_cache();sk980_audit('cache_clear_all','Cleared all detected application cache',$result,$uid,'warning');$flash='All detected application caches cleared.';}
  elseif($action==='reset_opcache'){$ok=function_exists('opcache_reset')?(bool)@opcache_reset():false;$result=['opcache_reset'=>$ok];sk980_audit('opcache_reset','Reset PHP OPcache',$result,$uid);$flash=$ok?'PHP OPcache reset.':'OPcache reset is unavailable.';}
  elseif($action==='clear_log'){if((string)($_POST['confirm_text']??'')!=='CLEAR LOG')throw new RuntimeException('Type exactly: CLEAR LOG');$result=sk980_clear_log((string)($_POST['log_id']??''));sk980_audit('log_clear','Cleared system log',$result,$uid,'warning');$flash='Selected log cleared.';}
  elseif($action==='retry_queue'){if((string)($_POST['confirm_text']??'')!=='RETRY FAILED')throw new RuntimeException('Type exactly: RETRY FAILED');$result=sk980_retry_queue((string)($_POST['queue_table']??''));sk980_audit('queue_retry','Retried failed queue records',$result,$uid,'warning');$flash='Failed queue records moved back to pending where supported.';}
  elseif($action==='maintenance_save'){$enabled=(string)($_POST['enabled']??'0')==='1'?'1':'0';$message=trim((string)($_POST['message']??''));$until=trim((string)($_POST['until']??''));sk980_save_setting('system_maintenance_enabled_v980',$enabled);sk980_save_setting('system_maintenance_message_v980',mb_substr($message,0,1000));sk980_save_setting('system_maintenance_until_v980',mb_substr($until,0,40));$result=['enabled'=>$enabled,'until'=>$until,'hook_installed'=>sk980_maintenance_hook_installed()];sk980_audit('maintenance_update','Updated maintenance mode settings',$result,$uid,$enabled==='1'?'warning':'info');$flash=$enabled==='1'?'Maintenance mode setting enabled.':'Maintenance mode disabled.';}
  elseif($action==='install_maintenance_hook'){if((string)($_POST['confirm_text']??'')!=='INSTALL MAINTENANCE HOOK')throw new RuntimeException('Type exactly: INSTALL MAINTENANCE HOOK');$result=sk980_install_maintenance_hook();sk980_audit('maintenance_hook_install','Installed global maintenance bootstrap hook',$result,$uid,'warning');$flash='Global maintenance hook installed with bootstrap backup.';}
  elseif($action==='restore_bootstrap'){if((string)($_POST['confirm_text']??'')!=='RESTORE BOOTSTRAP')throw new RuntimeException('Type exactly: RESTORE BOOTSTRAP');$result=sk980_uninstall_maintenance_hook();sk980_audit('maintenance_hook_restore','Restored pre-v9.8.0 bootstrap backup',$result,$uid,'warning');$flash='Bootstrap restore operation completed.';}
}
}catch(Throwable $e){$error=$e->getMessage();}

$health=sk980_server_health();$cache=sk980_cache_stats();$logs=sk980_log_files();$queues=sk980_queue_summary();$cron=sk980_cron_summary();$diag=sk980_diagnostics();$events=sk980_events();
